class Solution {
    public int climbStairs(int n) {
        // 记录爬到每一级台阶各有几种方法
        // (这里至少要记录前两级台阶的方法数，为了避免n=1时没有dp[1]产生数组越界报错，创建有n+1个元素的数组)
        int[] dp = new int[n + 1];
        // 爬到第一级台阶有1种方法
        dp[0] = 1;
        // 爬到第二级台阶有2种方法
        dp[1] = 2;

        if(n == 1 || n == 2){
            return dp[n-1];
        }

        // 爬到第三级台阶有3种方法：
        // 一种是先爬到第二级，然后从第二级爬1个台阶（dp[1]=2种情况是这样）
        // 另一种是先爬到第一级，然后从第一级爬2个台阶（dp[0]=1种方法是这样）
        // 以此类推，爬到第n级台阶有dp[n-2]+dp[n-1]种方法
        for(int i = 2; i < n; i++){
            dp[i] = dp[i-2] + dp[i-1];
        }

        return dp[n-1];
    }
}
